    // 10. Good news: community library
    [
        'slug' => 'retired-postman-turns-old-bus-into-free-library-for-odisha-villages',
        'category' => 'good-news',
        'page' => 'good-news-daily',
        'city' => null,
        'source' => 'IANS',
        'is_breaking' => false,
        'importance' => 5,
        'read_minutes' => 2,
        'minutes_ago' => 1450,
        'photo' => 'good-news-2.jpg',
        'en' => [
            'headline' => 'Retired postman turns old bus into free library for Odisha villages',
            'card_text' => 'A retired postman in Odisha\'s Ganjam district has turned a scrapped minibus into a free travelling library that now visits 14 villages every week. Hari Prasad Sahu, 64, began with 300 books from his own shelf. Donations have since grown the collection to over 6,000 books in Odia, Hindi and English, with about 900 regular readers.',
            'key_points' => [
                'The library bus visits 14 villages on a fixed weekly route.',
                'Its collection has grown from 300 books to more than 6,000 through donations.',
                'Around 900 people, most of them schoolchildren, borrow books regularly.',
            ],
            'why_it_matters' => 'Easy access to books in rural areas can improve reading habits and learning outcomes for children.',
            'simple_text' => 'Hari Prasad Sahu used to deliver letters as a postman in Odisha. After he retired, he bought an old minibus that nobody wanted, fixed it and filled it with books. Now the bus drives to 14 villages every week, and anyone can borrow a book for free. People from all over India have sent books, so the bus now carries more than 6,000 of them. Most of the readers are school children.',
            'full_text' => "When Hari Prasad Sahu retired after 36 years of delivering letters in the villages of Ganjam district, he noticed that many of the homes he once visited had almost no books. Four years later, the 64-year-old runs a free travelling library from a converted minibus that stops in 14 villages every week.\n\nSahu bought the scrapped vehicle at an auction for Rs 45,000, using part of his retirement savings. With help from a local mechanic and volunteers, he removed the seats, fitted wooden shelves and a small reading bench, and painted the outside with scenes from Odia folk tales. He started with 300 books from his own collection.\n\nWord spread through social media and local newspapers, and donations of books arrived from across the country. The library now holds more than 6,000 titles in Odia, Hindi and English, from picture books and comics to exam guides and novels. About 900 people borrow books regularly, most of them schoolchildren, who keep a book for a week and swap it on the bus's next visit.\n\n\"I carried letters to these families for decades. Now I carry stories,\" Sahu said. Two college students from Berhampur help him on weekends, and the block education office has offered space to set up a permanent reading room.",
        ],
        'hi' => [
            'headline' => 'सेवानिवृत्त डाकिये ने पुरानी बस को ओडिशा के गांवों के लिए मुफ्त लाइब्रेरी बनाया',
            'card_text' => 'ओडिशा के गंजाम ज़िले में एक सेवानिवृत्त डाकिये ने कबाड़ में पड़ी मिनी बस को मुफ्त चलती-फिरती लाइब्रेरी में बदल दिया है, जो हर हफ्ते 14 गांवों में जाती है। 64 वर्षीय हरि प्रसाद साहू ने अपनी 300 किताबों से शुरुआत की थी। अब दान से संग्रह 6,000 से ज़्यादा किताबों तक पहुंच गया है।',
            'key_points' => [
                'लाइब्रेरी बस तय साप्ताहिक रूट पर 14 गांवों में जाती है।',
                'दान की बदौलत संग्रह 300 से बढ़कर 6,000 से ज़्यादा किताबों का हो गया है।',
                'करीब 900 लोग नियमित रूप से किताबें लेते हैं, जिनमें ज़्यादातर स्कूली बच्चे हैं।',
            ],
            'why_it_matters' => 'गांवों में किताबों तक आसान पहुंच से बच्चों में पढ़ने की आदत और सीखने का स्तर दोनों बेहतर हो सकते हैं।',
            'simple_text' => 'हरि प्रसाद साहू ओडिशा में डाकिये थे और गांव-गांव चिट्ठियां पहुंचाते थे। रिटायर होने के बाद उन्होंने एक पुरानी मिनी बस खरीदी, जिसे कोई नहीं चाहता था। उन्होंने उसे ठीक कराया और उसमें किताबें भर दीं। अब यह बस हर हफ्ते 14 गांवों में जाती है और कोई भी मुफ्त में किताब ले सकता है। देशभर से लोगों ने किताबें भेजी हैं, इसलिए अब बस में 6,000 से ज़्यादा किताबें हैं। ज़्यादातर पाठक स्कूली बच्चे हैं।',
            'full_text' => "गंजाम ज़िले के गांवों में 36 साल तक चिट्ठियां बांटने के बाद जब हरि प्रसाद साहू सेवानिवृत्त हुए, तो उन्होंने गौर किया कि जिन घरों में वह जाते थे, उनमें से कई में किताबें लगभग न के बराबर थीं। चार साल बाद 64 वर्षीय साहू एक मिनी बस से मुफ्त चलती-फिरती लाइब्रेरी चलाते हैं, जो हर हफ्ते 14 गांवों में रुकती है।\n\nसाहू ने अपनी सेवानिवृत्ति की बचत से 45,000 रुपये में यह कबाड़ बस नीलामी में खरीदी थी। एक स्थानीय मैकेनिक और स्वयंसेवकों की मदद से उन्होंने सीटें हटाकर लकड़ी की अलमारियां और पढ़ने के लिए छोटी बेंच लगवाई, और बाहर ओड़िया लोक कथाओं के चित्र बनवाए। शुरुआत उनकी अपनी 300 किताबों से हुई।\n\nसोशल मीडिया और स्थानीय अखबारों के ज़रिये बात फैली तो देशभर से किताबें दान में आने लगीं। अब लाइब्रेरी में ओड़िया, हिंदी और अंग्रेज़ी की 6,000 से ज़्यादा किताबें हैं, जिनमें चित्र-पुस्तकें, कॉमिक्स, परीक्षा गाइड और उपन्यास शामिल हैं। करीब 900 लोग नियमित रूप से किताबें लेते हैं, जिनमें ज़्यादातर स्कूली बच्चे हैं।\n\nसाहू कहते हैं, \"दशकों तक मैं इन परिवारों तक चिट्ठियां ले गया, अब कहानियां ले जाता हूं।\" ब्रह्मपुर के दो कॉलेज छात्र सप्ताहांत में उनकी मदद करते हैं और ब्लॉक शिक्षा कार्यालय ने स्थायी वाचनालय के लिए जगह देने की पेशकश की है।",
        ],
    ],

];
